export function throttle(fn: () => void, maxPerWindow: number, windowMs: number): () => void {
  let requestsInWindow = 0;
  let lastReset = 0;

  return function () {
    const now = Date.now();
    if (now - lastReset > windowMs) {
      requestsInWindow = 0;
      lastReset = now;
    }

    if (requestsInWindow >= maxPerWindow) {
      return; // silently skip excess calls
    }

    requestsInWindow += 1;
    fn();
  };
}

// --- Self-test ---
if (import.meta.url === import.meta.url) {
  // Simulate running with: node throttle.ts
  const throttled = throttle(() => {
    console.log("fn called");
  }, 3, 2000);

  // Call 5 times within 2 seconds → fn should only be called 3 times
  throttled();
  throttled();
  throttled();
  throttled();
  throttled();

  const calls = [];
  const realFn = () => calls.push(Date.now());
  const t = throttle(realFn, 2, 100);

  t(); t(); t(); t(); t(); t(); // 7 calls, max 2 per 100ms

  if (calls.length !== 2) {
    throw new Error(`Expected 2 calls, got ${calls.length}`);
  }

  // Reset window and call again → should allow calls again
  const calls2 = [];
  const t2 = throttle(realFn, 2, 100);
  t2(); t2(); t2(); // 3 calls within window → fn called 2 times
  if (calls2.length !== 2) {
    throw new Error(`Expected 2 calls after reset, got ${calls2.length}`);
  }

  console.log("throttle self-test passed ✅");
}

